insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 46, 'Filho de Anzi, filho de Bani, filho de Semer,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 47, 'Filho de Mali, filho de Musi, filho de Merari, filho de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 48, 'E seus irmãos, os Levitas, foram postos para todo o serviço do tabernáculo da casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 49, 'E Arão e seus filhos ofereciam incenso sobre o altar do holocausto e sobre o altar do incenso, para toda a obra do lugar santíssimo, e para fazer expiação sobre Israel, conforme tudo quanto Moisés, servo de Deus, havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 50, 'E estes foram os filhos de Arão: seu filho Eleazar, seu filho Fineias, seu filho Abisua,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 51, 'Seu filho Buqui, seu filho Uzi, seu filho Zeraías,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 52, 'Seu filho Meraiote, seu filho Amarias, seu filho Aitube,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 53, 'Seu filho Zadoque, e seu filho Aimaaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 54, 'E estas foram suas habitações, conforme seus acampamentos e seus termos, dos filhos de Arão da família dos coatitas, porque eles foram sorteados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 55, 'Deram-lhes, pois, a Hebrom na terra de Judá, e seus campos ao redor dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 56, 'Porém o território da cidade e suas aldeias foram dadas a Calebe, filho de Jefoné.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 57, 'E aos filhos de Arão deram as [seguintes] cidades de refúgio: Hebrom, e Libna com seus campos; Jathir e Estemoa com seus campos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 58, 'Hilém com seus campos; Debir com seus campos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 59, 'Asã com seus campos; e a Bete-Semes com seus campos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 60, 'E da tribo de Benjamim, a Geba com seus campos; Alemete com seus campos; e Anatote com seus campos. Todas as suas cidades, [repartidas] por suas famílias, foram treze cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 61, 'Mas aos filhos de Coate, que restaram da família daquela tribo, [deram] por sorteio dez cidades da meia tribo de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 62, 'E aos filhos de Gérson, segundo suas famílias, [deram] treze cidades da tribo de Issacar, da tribo de Aser, da tribo de Naftali, e da tribo de Manassés, em Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 63, 'E aos filhos de Merari, segundo suas famílias, [deram] por sorteio doze cidades da tribo de Rúben, da tribo de Gade, e da tribo de Zebulom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 64, 'Assim os filhos de Israel deram aos Levitas estas cidades com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 65, 'E deram-lhes por sorteio, da tribo dos filhos de Judá, da tribo dos filhos de Simeão, e da tribo dos filhos de Benjamim, estas cidades, as quais mencionaram por seus nomes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 66, 'E quanto ao [resto] das famílias dos filhos de Coate deram-lhes cidades com seus termos da tribo de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 67, 'E deram-lhes das cidades de refúgio, a Siquém e seus campos nas montanhas de Efraim, e a Gezer com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 68, 'A Jocmeão com seus campos, a Bete-Horom com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 69, 'A Aijalom com seus campos, e a Gate-Rimom com seus campos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 70, 'Da meia tribo de Manassés, a Aner com seus campos, e a Bileã com seus campos, para os que restaram da família dos filhos de Coate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 71, 'Aos filhos de Gérson [deram] da família da meia tribo de Manassés, a Golã em Basã com seus campos e a Astarote com seus campos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 72, 'E da tribo de Issacar, a Quedes com seus campos, a Daberate com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 73, 'A Ramote com seus campos, e a Aném com seus campos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 74, 'E da tribo de Aser a Masal com seus campos, a Abdom com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 75, 'A Hucoque com seus campos, e a Reobe com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 76, 'E da tribo de Naftali, a Quedes na Galileia com seus campos, a Hamom com seus campos, e a Quiriataim com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 77, 'E aos que restaram dos filhos de Merari, [deram] da tribo de Zebulom, a Rimono com seus campos, e a Tabor com seus campos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 78, 'E dalém do Jordão de Jericó, ao oriente do Jordão, [deram] da tribo de Rúben, a Bezer no deserto com seus campos; a Jaza com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 79, 'A Quedemote com seus campos, e a Mefaate com seus campos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 80, 'E da tribo de Gade, a Ramote em Gileade com seus campos, a Maanaim com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 81, 'A Hesbom com seus campos, e a Jazer com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 1, 'Os filhos de Issacar foram quatro: Tolá, Pua, Jasube, e Sinrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 2, 'Os filhos de Tolá foram: Uzi, Refaías, Jeriel, Jamai, Ibsão e Samuel, cabeças das famílias de seus pais. De Tolá foram contados por suas genealogias no tempo de Davi vinte e dois mil seiscentos homens guerreiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 3, 'O filho de Uzi foi Izraías; e os filhos de Izraías foram: Micael, Obadias, Joel, e Issias; todos estes cinco foram líderes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 4, 'E havia com eles em suas genealogias, segundo as famílias de seus pais, trinta e seis mil homens de guerra, porque tiveram muitas mulheres e filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 5, 'E seus irmãos em todas as famílias de Issacar, todos contados por suas genealogias, foram oitenta e sete mil guerreiros valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 6, 'Os [filhos] de Benjamim foram três: Belá, Bequer, e Jediael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 7, 'Os filhos de Belá foram: Esbom, Uzi, Uziel, Jerimote, e Iri; cinco cabeças de famílias paternas, guerreiros valentes, dos quais foram contados por suas genealogias vinte e dois mil e trinta e quatro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 8, 'Os filhos de Bequer: Zemira, Joás, Eliézer, Elioenai, Onri, Jerimote, Abias, Anatote e Alemete; todos estes foram filhos de Bequer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 9, 'E foram contados por suas genealogias, segundo suas descendências, e os cabeças de suas famílias, vinte mil e duzentos guerreiros valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 10, 'E o filho de Jediael foi Bilã; e os filhos de Bilã foram: Jeús, Benjamim, Eúde, Quenaaná, Zetã, Társis, e Aisaar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 11, 'Todos estes filhos de Jediael foram cabeças de famílias, guerreiros valentes, dezessete mil e duzentos que saíam com o exército para a guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 12, 'Supim e Hupim foram filhos de Ir; e Husim foi filho de Aer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 13, 'Os filhos de Naftali foram: Jaziel, Guni, Jezer, e Salum, filhos de Bila.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 14, 'Os filhos de Manassés foram: Asriel, o qual foi nascido de sua concubina, a síria, a qual também lhe deu à luz Maquir, pai de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 15, 'E Maquir tomou por mulher a irmã de Hupim e Supim, cuja irmã teve por nome Maaca. O nome do segundo foi Zelofeade. E Zelofeade teve [somente] filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 16, 'E Maaca mulher de Maquir lhe gerou um filho, e chamou seu nome Perez; e o nome de seu irmão foi Seres, cujos filhos foram Ulão e Requém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 17, 'E o filho de Ulão foi Bedã. Estes foram os filhos de Gileade, filho de Maquir, filho de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 18, 'E sua irmã Hamolequete deu à luz Isode, Abiezer, e Maalá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 19, 'E os filhos de Semida foram Aiã, Siquém, Liqui, e Anião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 20, 'Os filhos de Efraim: Sutela, seu filho Berede, seu filho Taate, seu filho Eleada, seu filho Taate,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 21, 'Seu filho Zabade, seu filho Sutela, seu filho, Ézer, e Eleade. Mas os homens de Gate, naturais daquela terra, os mataram, porque desceram para tomar seus gados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 22, 'Por isso seu pai Efraim esteve de luto por muitos dias, e seus irmãos vieram consolá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 23, 'Depois ele se deitou com sua mulher, ela concebeu, e deu à luz um filho, ao qual chamou por nome Berias, pois o desastre havia ocorrido em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 24, 'E sua filha foi Seerá, a qual edificou a Bete-Horom, a baixa e a alta, como também a Uzém-Seerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 25, 'E seu filho foi Refa, seu filho Resefe, seu filho Telá, seu filho Taã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 26, 'Seu filho Laadã, seu filho Amiúde, seu filho Elisama,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 27, 'Seu filho Num, e seu filho Josué.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 28, 'E a propriedade e habitação deles foi Betel com suas aldeias, e ao oriente Naarã, e ao ocidente Gezer e suas aldeias, como também Siquém com suas aldeias, até Aia e suas aldeias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 29, 'E da parte dos filhos de Manassés, Bete-Seã com suas aldeias, Taanaque com suas aldeias, Megido com suas aldeias, e Dor com suas aldeias. Nestes [lugares] habitaram os filhos de José, filho de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 30, 'Os filhos de Aser foram: Imná, Isvá, Isvi, Berias, e sua irmã Sera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 31, 'Os filhos de Berias foram: Héber, e Malquiel, o qual foi pai de Bizarvite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 32, 'E Héber gerou a Jaflete, Semer, Hotão, e sua irmã Suá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 33, 'Os filhos de Jaflete foram: Pasaque, Bimal, e Asvate. Estes foram os filhos de Jaflete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 34, 'Os filhos de Semer foram: Aí, Roga, Jeubá, e Arã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 35, 'Os filhos de seu irmão Helém foram: Zofa, Imná, Seles, e Amal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 36, 'Os filhos de Zofa foram: Suá, Harnefer, Sual, Beri, Inra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 37, 'Bezer, Hode, Samá, Silsa, Iltrã e Beera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 38, 'Os filhos de Jéter foram: Jefoné, Pispa, e Ara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 39, 'E os filhos de Ula foram; Ara, Haniel, e Rizia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 7, 40, 'Todos estes foram filhos de Aser, cabeças de famílias paternas, escolhidos guerreiros valentes, chefes de príncipes; e foram contados em suas genealogias no exército para a guerra, em número de vinte e seis mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 1, 'Benjamim gerou a Belá seu primogênito, Asbel o segundo, Aará o terceiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 2, 'Noá o quarto, e Rafa o quinto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 3, 'E os filhos de Belá foram: Adar, Gera, Abiúde,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 4, 'Abisua, Naamã, Aoá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 5, 'Gera, Sefufá, e Hurão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 6, 'E estes foram os filhos de Eúde, os quais foram os cabeças das famílias dos moradores em Geba, que foram levados cativos a Manaate:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 7, 'Naamã, Aías, e Gera; este os levou cativos, e gerou a Uzá e a Aiúde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 8, 'E Saaraim gerou filhos na terra de Moabe, depois que deixou a suas mulheres Husim e Baara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 9, 'De sua mulher Hodes ele gerou a Jobabe, Zíbia, Messa, Malcã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 10, 'Jeús, Saquias, e Mirma. Estes foram seus filhos, cabeças de famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 11, 'E de Husim ele gerou a Abitube, e a Elpaal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 12, 'E os filhos de Elpaal foram: Héber, Misã, Semede (o qual edificou a Ono e a Lode com suas aldeias),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 13, 'Assim como Berias, e Sema, que foram cabeças das famílias dos moradores de Aijalom, os quais afugentaram aos moradores de Gate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 14, 'E Aiô, Sasaque, Jeremote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 15, 'Zebadias, Arade, Eder;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 16, 'Micael, Ispa, e Joá, foram filhos de Berias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 17, 'E Zebadias, Mesulão, Hizqui, Héber,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 18, 'Ismerai, Izlias, e Jobabe, foram filhos de Elpaal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 19, 'E Jaquim, Zicri, Zabdi,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 20, 'Elioenai, Ziletai, Eliel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 21, 'Adaías, Beraías, e Sinrate, foram filhos de Simei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 22, 'E Ispã, Héber, Eliel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 23, 'Abdom, Zicri, Hanã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 24, 'Hananias, Elão, Antotias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 25, 'Ifdeias, e Penuel, foram filhos de Sasaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 26, 'E Sanserai, Searias, Atalias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 27, 'Jaaresias, Elias, e Zicri, foram filhos de Jeroão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 28, 'Estes foram cabeças de famílias, chefes segundo suas gerações; estes habitaram em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 29, 'E em Gibeão habitou o pai de Gibeão; e o nome de sua mulher era Maaca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 30, 'E seu filho primogênito foi Abdom; depois Zur, Quis, Baal, Nadabe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 31, 'Gedor, Aiô, Zequer,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 32, 'E Miclote, que gerou a Simeia. Estes também habitaram perto de irmãos em Jerusalém, vizinhos a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 33, 'E Ner gerou a Quis; Quis gerou a Saul, e Saul gerou a Jônatas, Malquisua, Abinadabe, e a Esbaal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 34, 'O filho de Jônatas foi Meribe-Baal, e Meribe-Baal gerou a Mica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 35, 'Os filhos de Mica foram: Pitom, Meleque, Tareia e Acaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 36, 'E Acaz gerou a Jeoada; e Jeoada gerou a Alemete, a Azmavete, e a Zinri; e Zinri gerou a Moza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 37, 'E Moza gerou a Bineá, cujo filho foi Rafa, cujo filho foi Eleasá, cujo filho foi Azel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 38, 'Azel teve seis filhos, cujos nomes foram: Azricão, Bocru, Ismael, Searias, Obadias, e Hanã; todos estes foram filhos de Azel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 39, 'E os filhos de Eseque, seu irmão, foram: Ulão seu primogênito, Jeús o segundo, e Elifelete o terceiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 8, 40, 'E os filhos de Ulão foram guerreiros valentes, hábeis flecheiros; e tiveram muitos filhos e netos, cento e cinquenta. Todos estes foram dos filhos de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 1, 'E todo Israel foi contado por genealogias, e eis que foram escritos no livro dos Reis de Israel e de Judá, que foram transportados para a Babilônia por causa de sua transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 2, 'E os primeiros habitantes que vieram a suas propriedades em suas cidades, foram os israelitas, os sacerdotes, os levitas, e os servos do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 3, 'Porém em Jerusalém habitaram [alguns] dos filhos de Judá, dos filhos de Benjamim, dos filhos de Efraim e de Manassés;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 4, 'Utai, filho de Amiúde, filho de Onri, filho de Inri, filho de Bani, dos filhos de Perez filho de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 5, 'E dos silonitas: Asaías o primogênito, e seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 6, 'E dos filhos de Zerá, Jeuel e seus irmãos, seiscentos e noventa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 7, 'E dos filhos de Benjamim: Salu, filho de Mesulão, filho de Hodavias, filho de Hassenua;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 8, 'E Ibneias, filho de Jeroão; e Elá filho de Uzi, filho de Micri; e Mesulão filho de Sefatias, filho de Reuel, filho de Ibneias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 9, 'E seus irmãos, segundo suas genealogias, foram novecentos e cinquenta e seis; todos estes homens foram cabeças das famílias de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 10, 'E dos sacerdotes: Jedaías, Jeoiaribe, Jaquim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 11, 'E Azarias filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, príncipe da casa de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 12, 'E Adaías filho de Jeroão, filho de Pasur, filho de Malquias; e Masai filho de Adiel, filho de Jazera, filho de Mesulão, filho de Mesilemite, filho de Imer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 13, 'Como também seus irmãos, cabeças das famílias de seus pais, mil setecentos e sessenta, homens valentes e hábeis para a obra do serviço da casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 14, 'E dos Levitas: Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, dos filhos de Merari;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 15, 'E Baquebacar, Heres, Galal, e Matanias filho de Mica, filho de Zicri, filho de Asafe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 16, 'E Obadias filho de Semaías, filho de Galal, filho de Jedutum; e Berequias filho de Asa, filho de Elcana, que habitou nas aldeias de Netofate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 17, 'E os porteiros foram: Salum, Acube, Talmom, Aimã, e seus irmãos cujo líder era Salum,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 18, '(O qual até agora fica junto à porta do rei ao oriente). Estes foram os porteiros do acampamento dos filhos de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 19, 'E Salum, filho de Coré, filho de Ebiasafe, filho de Corá, e seus irmãos da família de seu pai, os coraítas, foram encarregados da obra do serviço, guardando os umbrais do tabernáculo; assim como seus pais foram capitães do acampamento do SENHOR, que guardavam a entrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 20, 'E Fineias, filho de Eleazar, havia sido antes comandante sobre eles, e o SENHOR era com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 21, 'E Zacarias, filho de Meselemias, era porteiro da porta da tenda do ajuntamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 22, 'Todos estes, escolhidos para porteiros dos umbrais, foram duzentos e doze; e estes foram registrados em suas genealogias, segundo suas aldeias; e Davi e o vidente Samuel os constituíram em seu ofício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 23, 'Assim eles e seus filhos estiveram junto às portas da casa do SENHOR, a casa do Tabernáculo, como guardas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 24, 'Os porteiros estavam aos quatro ventos: ao oriente, ao ocidente, ao norte, e ao sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 25, 'E seus irmãos que estavam em suas aldeias vinham de tempos em tempos para durante sete dias [servirem] com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 26, 'Pois havia naquele ofício chefes dos porteiros, que eram levitas; e eles eram encarregados das câmaras e dos tesouros da casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 27, 'E passavam a noite ao redor da casa de Deus, porque eram responsáveis pela guarda, e por abri-la a cada manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 28, 'Alguns destes eram encarregados dos utensílios do serviço, pois os colocavam contados, e contados os tiravam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 29, 'E outros deles eram encarregados da mobília, e de todos os utensílios do santuário, como também da farinha, do vinho, do azeite, do incenso, e das especiarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 30, 'E alguns dos filhos dos sacerdotes faziam o perfume das especiarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 31, 'E Matitias, um dos Levitas, primogênito de Salum o coraíta, era encarregados das coisas que se faziam em assadeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 32, 'E alguns de seus irmãos, dos filhos dos coatitas, eram encarregados dos pães da proposição, para os prepararem para todos os sábados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 33, 'E destes também havia os cantores, cabeças das famílias dos levitas, os quais estavam isentos [de outros serviços] em suas câmaras, porque de dia e de noite estavam encarregados naquela obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 34, 'Estes foram os cabeças das famílias dos levitas, cabeças em suas genealogias, os quais habitaram em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 35, 'E em Gibeão habitaram: Jeiel, pai de Gibeão (e o nome de sua mulher era Maaca);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 36, 'E seu filho primogênito Abdom, depois Zur, Quis, Baal, Ner, Nadabe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 37, 'Gedor, Aiô, Zacarias, e Miclote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 38, 'E Miclote gerou a Simeia. E também estes habitaram em Jerusalém junto de seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 39, 'E Ner gerou a Quis, Quis gerou a Saul, e Saul gerou a Jônatas, a Malquisua, a Abinadabe, e a Esbaal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 40, 'E filho de Jônatas foi Meribe-Baal; e Meribe-Baal gerou a Mica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 41, 'E os filhos de Mica foram: Pitom, Meleque, Tareia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 42, '[E] Acaz, [que] gerou a Jará, Jará gerou a Alemete, a Azmavete, e a Zinri; e Zinri gerou a Moza;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 43, 'E Moza gerou a Bineá, cujo filho foi Refaías, cujo filho foi Eleasá, cujo filho foi Azel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 9, 44, 'E Azel teve seis filhos, cujos nomes foram: Azricão, Bocru, Ismael, Searias, Obadias, e Hanã; estes foram os filhos de Azel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 1, 'Os filisteus guerrearam contra Israel; e os homens de Israel fugiram diante deles, e caíram feridos no monte de Gilboa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 2, 'E os filisteus perseguiram a Saul e a seus filhos; e os filisteus mataram Jônatas, Abinadabe, e Malquisua, filhos de Saul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 3, 'E a batalha se dificultou sobre Saul; os flecheiros o alcançaram, e ele foi ferido pelos flecheiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 4, 'Então Saul disse a seu escudeiro: Tira a tua espada, e atravessa-me com ela, para que não aconteça que estes incircuncisos venham, e escarneçam de mim.Porém seu escudeiro não quis, porque tinha muito medo. Então Saul tomou a espada, e se lançou sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 5, 'E quando seu escudeiro viu que Saul estava morto, ele também se lançou sobre sua espada, e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 6, 'Assim Saul e seus três filhos morreram; e toda a sua casa morreu juntamente com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 7, 'E quando todos os homens de Israel que estavam no vale viram que [o exército] havia fugido, e que Saul e seus filhos estavam mortos, deixaram suas cidades, e fugiram; então os filisteus vieram, e habitaram nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 8, 'E no dia seguinte, quando os Filisteus vieram para despojar os mortos, acharam Saul e seus filhos estendidos no monte de Gilboa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 9, 'Então o despiram, tomaram sua cabeça e suas armas, e as enviaram por toda a terra dos filisteus para anunciarem a seus ídolos e ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 10, 'E puseram suas armas no templo de seu deus, e colocaram sua cabeça no templo de Dagom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 11, 'E quando todos os de Jabes-Gileade ouviram tudo quanto filisteus haviam feito a Saul,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 12, 'Todos os homens valentes se levantaram, tomaram o corpo de Saul e os corpos de seus filhos, e os trouxeram a Jabes; e sepultaram seus ossos debaixo de um carvalho em Jabes, e jejuaram durante sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 13, 'Assim Saul morreu por sua transgressão com que havia transgredido contra o SENHOR, por causa da palavra do SENHOR, a qual ele não obedeceu; e por ter buscado à médium para lhe consultar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 10, 14, 'E não ter buscado ao SENHOR. Por isso ele o matou, e passou o reino a Davi, filho de Jessé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 1, 'Então todo o Israel se ajuntou a Davi em Hebrom, dizendo: Eis que nós somos teu osso e tua carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 2, 'E mesmo antes, quando Saul ainda era rei, tu conduzias as tropas de Israel. Também o SENHOR teu Deus te disse: Tu apascentarás o meu povo Israel, e tu serás líder do meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 3, 'Também vieram todos os anciãos de Israel ao rei em Hebrom, e Davi fez aliança com eles diante do SENHOR; e ungiram a Davi como rei sobre Israel, conforme a palavra do SENHOR por meio de Samuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 4, 'Então Davi e todo Israel foram a Jerusalém, a qual era Jebus, pois ali os jebuseus eram os moradores daquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 5, 'E os moradores de Jebus disseram a Davi: Tu não entrarás aqui.Porém Davi conquistou a fortaleza de Sião, que é a cidade de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 6, '(Pois Davi havia dito: O primeiro a derrotar aos jebuseus será chefe e comandante.Então Joabe, filho de Zeruia, subiu primeiro, e foi feito comandante.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 7, 'E Davi habitou na fortaleza; por isso que foi chamada de cidade de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 8, 'E ele edificou a cidade ao redor, desde as fundações do aterro ao redor; e Joabe reparou o resto da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 9, 'E Davi ia cada vez mais crescendo em poder, pois o SENHOR dos exércitos era com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 10, 'Estes foram os líderes dos guerreiros que Davi teve, os que lhe deram forte apoio em seu reinado, com todo Israel, para o fazerem rei sobre Israel, conforme a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 11, 'E este é o número dos guerreiros que Davi teve: Jasobeão, filho de Hacmoni, chefe de capitães, o qual, fazendo uso de sua lança, matou trezentos de um vez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 12, 'E depois dele Eleazar, filho de Dodô, o aoíta; ele era um dos três principais guerreiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 13, 'Este esteve com Davi em Pas-Damim, quando os filisteus se ajuntaram para a batalha; e havia ali uma plantação cheia de cevada. Enquanto o povo fugia dos filisteus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 14, 'Eles se puseram no meio da plantação, defenderam-na, e derrotaram os Filisteus; e o SENHOR lhes deu uma grande vitória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 15, 'E três dos trinta comandantes desceram a Davi, na rocha junto à caverna de Adulão, enquanto o acampamento dos filisteus estava no vale de Refaim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 16, 'E Davi estava então na fortaleza, enquanto havia uma tropa de filisteus em Belém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 17, 'Davi teve um desejo, e disse: Quem me dera beber da água do poço de Belém, que está junto à porta!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 18, 'E aqueles três irromperam pelo acampamento dos filisteus, e tiraram água do poço de Belém, que está junto à porta, tomaram dela, e a trouxeram a Davi. Davi, porém não a quis beber; em vez disso, derramou-a ao SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 19, 'E disse: Deus me proíba de fazer isto! Beberia eu o sangue destes homens com suas vidas? Pois eles arriscaram suas vidas para a trazerem.Por isso ele não a quis beber. Isto fizeram aqueles três guerreiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 20, 'E também Abisai, irmão de Joabe, foi o cabeça de três, o qual usando sua lança sobre trezentos, ele os matou; e foi famoso entre os três.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 21, 'Dos três ele foi mais ilustre que os outros dois, por isso foi seu cabeça; porém não alcançou os três [primeiros] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 22, '[Também] Benaia, filho de Joiada, filho de homem valente, de grandes feitos, de Cabzeel; ele matou dois dos poderosos guerreiros de Moabe; ele também desceu, e matou um leão dentro de uma cova no tempo da neve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 23, 'Ele também matou um homem egípcio alto, de cinco côvados; o egípcio trazia na mão uma lança como um lançador de tecelão; porém [Benaia] desceu a ele com um bastão; e arrancou a lança da mão do egípcio, e o matou com sua própria lança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 24, 'Estas coisas fez Benaia, filho de Joiada, e por isso foi famoso entre aqueles três guerreiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 25, 'Eis que ele foi o mais ilustre dos trinta, mas não alcançou os três [primeiros] . E Davi o pôs sobre sua guarda pessoal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 26, 'E os guerreiros dos exército foram: Asael, irmão de Joabe; Elanã filho de Dodô de Belém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 27, 'Samote o harodita; Helez o pelonita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 28, 'Ira, filho de Iques, o tecoíta; Abiezer o anatotita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 29, 'Sibecai o husatita; Ilai o aoíta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 30, 'Maarai o netofatita; Helede, filho de Baaná, o netofatita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 31, 'Itai, filho de Ribai, de Gibeá dos filhos de Benjamim; Benaia o piratonita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 32, 'Hurai do ribeiro de Gaás; Abiel, o arbatita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 33, 'Azmavete, o baarumita; Eliaba, o saalbonita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 34, 'Os filhos de Hasém, o gizonita; Jônatas, filho de Sage, o hararita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 35, 'Aião filho de Sacar, o hararita; Elifal filho de Ur;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 36, 'Héfer, o mequeratita; Aías, o pelonita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 37, 'Hezro, o carmelita; Naarai, filho de Ezbai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 38, 'Joel, irmão de Natã; Mibar, filho de Hagri;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 39, 'Zeleque, o amonita; Naarai, o berotita, escudeiro de Joabe filho de Zeruia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 40, 'Ira, o itrita; Garebe, o itrita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 41, 'Urias, o heteu; Zabade, filho de Alai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 42, 'Adina, filho de Siza, o rubenita, [o qual era] chefe dos rubenitas, e com ele trinta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 43, 'Hanã, filho de Maaca; Josafá o mitenita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 44, 'Uzia, o asteratia; Sama e Jeiel, filhos de Hotão, o aroerita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 45, 'Jedaiel, filho de Sinri, e seu irmão Joá, o tizita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 46, 'Eliel, o maavita; Jeribai e Josavias, filhos de Elnaão; Itma, o moabita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 11, 47, 'Eliel; Obede; e Jaasiel, o mezobaíta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 1, 'Estes, pois, foram os que vieram a Davi a Ziclague, enquanto ele ainda estava escondido por causa de Saul filho de Quis; e eles estiveram entre os guerreiros que o ajudaram na guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 2, 'Eles estavam armados de arcos, e podiam tanto com a mão direita como a esquerda atirar pedras com funda, e setas com arco. Estes eram dentre os irmãos de Saul, os benjamitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 3, 'Aiezer, o cabeça; e Joás, filhos de Semaá o gibeatita; e Jeziel, e Pelete, filhos de Azmavete; e Beraca, e Jeú o anatotita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 4, 'E Ismaías, o gibeonita, valente entre os trinta, e capitão dos trinta; e Jeremias, Jaaziel, Joanã, Jozabade o gederatita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 5, 'Eluzai, Jeremote, Bealias, Semarias, e Sefatias o harufita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 6, 'Elcana, Issias, Azareel, Joezer, e Jasobeão, os coraítas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 7, 'E Joela e Zebadias, filhos de Jeroão de Gedor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 8, 'E [alguns] dos gaditas passaram a Davi, à fortaleza no deserto, guerreiros valentes, homens de guerra para lutar, armados com escudo e lança; seus rostos eram como rostos de leões, e velozes como as corças sobre os montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 9, 'Ézer o cabeça, Obadias o segundo, Eliabe o terceiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 10, 'Mismana o quarto, Jeremias o quinto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 11, 'Atai o sexto, Eliel o sétimo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 12, 'Joanã o oitavo, Elzabade o nono,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 13, 'Jeremias o décimo, Macbanai o décimo primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 14, 'Estes foram os capitães do exército dos filhos de Gade. O menor tinha autoridade sobre cem homens, e o maior sobre mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 15, 'Estes foram os que passaram o Jordão no mês primeiro, quando ele estava transbordando sobre todas as suas margens; e fizeram fugir a todos os dos vales ao oriente e ao ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 16, 'Também alguns dos filhos de Benjamim e de Judá vieram a Davi à fortaleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 17, 'E Davi saiu ao encontro deles, e lhes falou, dizendo: Se viestes a mim para paz e para me ajudar, meu coração será unido convosco; mas se é para me entregar a meus inimigos, mesmo sendo meus mãos sem crime, o Deus de nossos pais o veja, e o repreenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 18, 'Então o Espírito revestiu a Amasai, chefe de trinta, e disse: Teus somos, ó Davi! E contigo estamos, ó filho de Jessé! Paz, paz seja contigo, e paz com os teus ajudadores; pois o teu Deus te ajuda.E Davi os recebeu, e os constituiu entre os capitães das tropas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 19, 'Também alguns de Manassés passaram a Davi, quando ele veio com os filisteus à batalha contra Saul, ainda que não os ajudaram; porque os líderes dos filisteus, [depois de terem feito] conselho, o despediram, dizendo: Com nossas cabeças ele passará a seu senhor Saul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 20, 'Quando, pois, ele veio a Ziclague, passaram-se a ele dos de Manassés: Adna, Jozabade, Jediaiel, Micael, Jozabade, Eliú, e Ziletai, chefes de milhares dos de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 21, 'E estes ajudaram a Davi contra aquela tropa; porque todos eles eram guerreiros valentes, e foram capitães no exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 22, 'Pois naquele tempo todos os dias, eles vinham a Davi para o ajudar, até que se fez um grande exército, como um exército de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 23, 'E este são os números dos chefes armados para a batalha, que vieram a Davi em Hebrom, para passar a ele o reino de Saul, conforme a palavra do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 24, 'Dos filhos de Judá que traziam escudo e lança, seis mil e oitocentos, armados para a batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 25, 'Dos filhos de Simeão, guerreiros valentes para batalhar, sete mil e cem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 26, 'Dos filhos de Levi, quatro mil e seiscentos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 27, 'Joiada, porém, era o comandante dos [descendentes] de Arão, e com ele três mil e setecentos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 28, 'E Zadoque, era um jovem guerreiro valente, e da família de seu pai vinte e dois líderes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 29, 'Dos filhos de Benjamim, irmãos de Saul, três mil; porque até então ainda havia muitos deles que ainda trabalhavam pela casa de Saul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 30, 'Dos filhos de Efraim, vinte mil e oitocentos, guerreiros valentes, homens ilustres nas casas de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 31, 'Da meia tribo de Manassés, dezoito mil, que foram convocados por nome para virem a tornar Davi rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 32, 'Dos filhos de Issacar, conhecedores dos tempos, para saberem o que Israel devia fazer, duzentos de seus líderes; e todos os seus irmãos seguiam suas ordens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 33, 'E de Zebulom, cinquenta mil, que saíam como exército preparados para a batalha, com todas as armas de guerra; capazes de batalhar com firmeza de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 34, 'E de Naftali mil capitães, e com eles trinta e sete mil com escudo e lança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 35, 'E dos danitas, preparados para a batalha, vinte e oito mil e seiscentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 36, 'E de Aser, dos que saíam como exército, prontos para a batalha, quarenta mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 37, 'E dalém do Jordão, dos rubenitas, dos gaditas, e da meia tribo de Manassés, como toda variedade de armas de guerra para batalhar, cento e vinte mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 38, 'Todos estes homens de guerra, postos em posição de batalha, com coração íntegro, vieram a Hebrom, para constituir Davi rei sobre todo Israel; e também todos os demais de Israel tinham a mesma intenção de constituir Davi o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 39, 'E estiveram ali com Davi três dias, comendo e bebendo, porque seus irmãos haviam lhes feito preparativos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 12, 40, 'E também os seus vizinhos, até de Issacar, Zebulom, e Naftali, trouxeram pão sobre asnos, camelos, mulos, e bois; e alimento de farinha, bolos de figos e passas, vinho e azeite, bois e ovelhas em abundância, porque havia alegria em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 1, 'Então Davi teve conselho com os capitães de milhares e de centenas, [e] com todos os chefes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 2, 'E Davi disse a todo a congregação de Israel: Se bem vos parece, e se vem do SENHOR nosso Deus, enviemos depressa [mensageiros] aos nossos irmãos que restaram em todas as terras de Israel, aos sacerdotes e aos levitas que estão com eles em suas cidades e em seus arredores, para que se ajuntem conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 3, 'E tragamos de volta a nós a arca de nosso Deus, porque não a buscamos desde o tempo de Saul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 4, 'Então toda a congregação disse que assim se fizesse, porque isso pareceu correto aos olhos de todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 5, 'Assim Davi ajuntou a todo Israel, desde Sior do Egito, até chegar a Hamate, para que trouxessem a arca de Deus de Quriate-Jearim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 6, 'Então Davi subiu com todo Israel a Baalá, [que é] Quriate-Jearim, em Judá, para dali trazerem acima a arca de Deus, o SENHOR, que habita entre os querubins, a qual é chamada pelo seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 7, 'E levaram a arca de Deus da casa de Abinadabe sobre uma carruagem nova, e Uzá e seu irmão guiavam o carro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 8, 'E Davi e todo Israel celebravam diante de Deus com toda força; e com canções, harpas, saltérios, tamboris, címbalos e com trombetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 9, 'E quando chegaram à eira de Quidom, Uzá estendeu sua mão para segurar a arca, pois os bois tropeçaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 10, 'Então a ira do SENHOR se acendeu contra Uzá, e o feriu, por ele ter estendido sua mão à arca; e morreu ali diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 11, 'E Davi teve desgosto, porque o SENHOR havia atingido Uzá; por isso ele chamou aquele lugar Perez-Uzá, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 12, 'E Davi temeu a Deus naquele dia, dizendo: Como trarei a mim a arca de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 13, 'Por isso Davi não trouxe a arca a si, à cidade de Davi; em vez disso ele a trouxe à casa de Obede-Edom, o geteu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 13, 14, 'Assim a arca de Deus ficou na casa de Obede-Edom, em sua casa, por três meses; e o SENHOR abençoou a casa de Obede-Edom, e tudo quanto ele tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 1, 'Então Hirão, rei de Tiro, enviou mensageiros a Davi, e também madeira de cedro, pedreiros e carpinteiros, para lhe edificarem uma casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 2, 'E Davi entendeu que o SENHOR o tinha confirmado por rei sobre Israel, pois seu reino tinha sido exaltado, por causa de seu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 3, 'E Davi teve mais esposas em Jerusalém, e Davi ainda gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 4, 'E estes são os nomes dos filhos que teve em Jerusalém: Samua, Sobabe, Natã, Salomão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 5, 'Ibar, Elisua, Elpelete,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 6, 'Nogá, Nefegue, Jafia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 7, 'Elisama, Beeliada e Elifelete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 8, 'Quando, pois, os filisteus ouviram que Davi havia sido ungido rei sobre todo Israel, todos os filisteus subiram em busca de Davi. E quando Davi ouviu falar disso, logo saiu contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 9, 'E os filisteus vieram e ocuparam o vale de Refaim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 10, 'Então Davi consultou a Deus, dizendo: Subirei contra os filisteus? E tu os entregarás em minhas mãos?E o SENHOR lhe disse: Sobe, porque eu os entregarei em teus mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 11, 'Davi subiu, pois, Baal-Perazim, e ali os derrotou. Então Davi disse: Por minha mão Deus rompeu meus inimigos, como se rompem as águas.Por isso chamaram o nome daquele lugar Baal-Perazim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 12, 'E ali deixaram seus deuses, e Davi mandou que fossem queimados a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 13, 'Porém os filisteus voltaram a ocupar o vale.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 14, 'Então Davi voltou a consultar a Deus, e Deus lhe disse: Não subas por trás deles; em vez disso rodeia-os, e vem contra eles em frente das amoreiras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 15, 'E será que ouvires, quando tu ouvires o ruído do marchar [das tropas] pelas copas das amoreiras, então sai à batalha; porque Deus sairá adiante de ti para derrotar o acampamento dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 16, 'E Davi fez como Deus lhe mandara, e feriram o acampamento dos filisteus desde Gibeão até Gezer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 14, 17, 'E a fama de Davi se espalhou por todas aquelas terras; e o SENHOR fez todas aquelas nações temerem a Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 1, 'Davi também fez casas para si em sua cidade, e preparou um lugar para a arca de Deus, e lhe armou uma tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 2, 'Então Davi disse: Ninguém pode trazer a arca de Deus, a não ser os levitas; porque o SENHOR os escolheu para que transportassem a arca do SENHOR, e para lhe servirem eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 3, 'E Davi ajuntou a todo Israel em Jerusalém, para fazerem subir a arca do SENHOR a seu lugar, que ele tinha lhe preparado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 4, 'Davi também ajuntou aos filhos de Arão e aos levitas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 5, 'Dos filhos de Coate, Uriel o principal, e seus irmãos, cento e vinte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 6, 'Dos filhos de Merari, Asaías o principal, e seus irmãos, duzentos e vinte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 7, 'Dos filhos de Gérson, Joel o principal, e seus irmãos, cento e trinta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 8, 'Dos filhos de Elisafã, Semaías o principal, e seus irmãos, duzentos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 9, 'Dos filhos de Hebrom, Eliel o principal, e seus irmãos, oitenta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 10, 'Dos filhos de Uziel, Amidadabe o principal, e seus irmãos, cento e doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 11, 'E Davi chamou aos sacerdotes Zadoque e Abiatar, e a os levitas Uriel, Asaías, Joel, Semaías, Eliel, e Aminadabe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 12, 'E disse-lhes: Vós que sois os chefes das famílias entre os levitas, santificai-vos, vós e vossos irmãos, e fazei subir a arca do SENHOR, Deus de Israel, ao lugar que eu lhe preparei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 13, 'Pois por não terdes feito assim vós da primeira vez, o SENHOR nosso Deus fez nos atingiu, porque não o buscamos conforme o mandamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 14, 'Assim os sacerdotes e os levitas se santificaram para trazerem a arca do SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 15, 'E os filhos dos levitas trouxeram a arca de Deus com as barras sobre seus ombros, assim como Moisés tinha mandado conforme a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 16, 'E Davi disse aos chefes dos levitas que constituíssem de seus irmãos cantores com instrumentos musicais, com saltérios, e harpas, e címbalos; para que fizessem sons e levantassem a voz com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 17, 'Então os levitas constituíram a Hemã, filho de Joel; e de seus irmãos, a Asafe filho de Berequias; e dos filhos de Merari e de seus irmãos, a Etã filho de Cusaías;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 18, 'E com eles a seus irmãos da segundo ordem, a Zacarias, Bene e Jaaziel, Semiramote, Jeiel, Uni, Eliabe, Benaia, Maaseias, Matitias, Elifeleu, Micneias, Obede-Edom, e Jeiel, os porteiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 19, 'E os cantores: Hemã, Asafe, e Etã, fizeram sons com címbalos de metal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 20, 'E Zacarias, Aziel, Semiramote, Jeiel, Uni, Eliabe, Maaseias, e Benaia, com saltérios sobre Alamote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 21, 'E Matitias, Elifeleu, Micneias, Obede-Edom, Jeiel, e Azazias, tocavam ao modo de Seminite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 22, 'E Quenanias, chefe dos levitas, estava encarregado de conduzir o cântico; ele ensinava o cântico porque era entendido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 23, 'E Berequias e Elcana eram porteiros da arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 24, 'E os sacerdotes Sebanias, Josafá, Natanael, Amasai, Zacarias, Benaia, e Eliézer, tocavam as trombetas diante da arca de Deus; e Obede-Edom e Jeías eram porteiros da arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 25, 'Sucedeu, pois, que Davi, os anciãos de Israel, e os capitães de milhares, foram fazer subir a arca do pacto do SENHOR, de casa de Obede-Edom, com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 26, 'E foi que, por Deus estar ajudando os levitas que levavam a arca do pacto do SENHOR, eles sacrificaram sete novilhos e sete carneiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 27, 'E Davi ia vestido de um roupão de linho fino, como também todos os levitas que levavam a arca, e os cantores; e Quenanias era o chefe da música e dos cantores. Davi também levava sobre si um éfode de linho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 28, 'Assim todo Israel fez subir a arca do pacto do SENHOR, com júbilo, som de cornetas e trombetas, e címbalos, e ao som de saltérios e harpas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 15, 29, 'E foi que, quando a arca do pacto do SENHOR chegou à cidade de Davi, Mical, filha de Saul, olhou por uma janela, e viu o rei Davi dançando e saltando; e ela o desprezou em seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 1, 'Trouxeram, pois, a arca de Deus, e a puseram no meio da tenda que Davi havia lhe armado; e apresentaram holocaustos e sacrifícios de gratidão diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 2, 'E Davi, quando terminou de apresentar os holocaustos e os sacrifícios de gratidão, abençoou ao povo em nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 3, 'E repartiu a todos em Israel, tanto homens como mulheres, a cada um um bolo de pão, uma boa porção de carne, e um bolo de passas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 4, 'E pôs diante do arca do SENHOR a [alguns] dos levitas como servidores, para que celebrassem, agradecessem, e louvassem ao SENHOR Deus de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 5, 'Asafe era o cabeça, e Zacarias era o segundo depois; Jeiel, Semiramote, Jeiel, Matitias, Eliabe, Benaia, Obede-Edom, e Jeiel, estavam com seus instrumentos de saltérios e harpas, mas Asafe fazia som com címbalos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 6, 'Porém os sacerdotes Benaia e Jaaziel estavam continuamente com trombetas diante do arca do pacto de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 7, 'Então naquele mesmo dia Davi pela primeira vez mandou celebrarem ao SENHOR por meio de Asafe e de seus irmãos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 8, 'Louvai ao SENHOR, invocai o seu nome, notificai entre os povos os seus feitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 9, 'Cantai a ele, cantai-lhe salmos; falai de todas as suas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 10, 'Gloriai-vos em seu santo nome; alegre-se o coração dos que buscam ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 11, 'Procurai ao SENHOR e à sua força; buscai a sua face continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 12, 'Lembrai-vos de suas maravilhas que ele fez, de seus prodígios, e dos juízos de sua boca,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 13, 'Vós, descendentes de seu servo Israel, vós filhos de Jacó, seus escolhidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 14, 'Ele é o SENHOR, o nosso Deus; seus juízos estão em toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 15, 'Lembrai-vos perpetuamente de seu pacto, [e] da palavra que ele mandou até mil gerações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 16, 'Do pacto que estabeleceu com Abraão, e do seu juramento a Isaque;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 17, 'O qual confirmou a Jacó por estatuto, a Israel por pacto eterno,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 18, 'Dizendo: A ti darei a terra de Canaã, a porção de vossa herança;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 19, 'Quando vós éreis poucos em número, poucos, e estrangeiros nela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 20, 'Que andavam de nação em nação, de um reino a outro povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 21, 'A ninguém ele permitiu que os oprimisse; por causa deles repreendeu a reis,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 22, '[Dizendo] : Não toqueis em meus ungidos, nem façais mal a meus profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 23, 'Cantai ao SENHOR, toda a terra, anunciai de dia em dia sua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 24, 'Cantai entre as nações sua glória, e entre todos os povos suas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 25, 'Porque o SENHOR é grande, e muito digno de ser louvado; ele é mais temível que todos os deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 26, 'Pois todos os deuses dos povos nada são; porém o SENHOR fez os céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 27, 'Majestade e esplendor há diante de ele; força e alegria em sua morada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 28, 'Reconhecei ao SENHOR, ó famílias das nações, reconhecei ao SENHOR a glória e o poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 29, 'Dai ao SENHOR a glória de seu nome; trazei ofertas, e vinde diante dele; adorai ao SENHOR na glória de sua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 30, 'Assombrai-vos diante dele, vós, toda a terra; o mundo [por ele] foi estabelecido, para que não se movesse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 31, 'Alegrem-se os céus, e goze-se a terra, e digam nas nações: Reina o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 32, 'Ressoe o mar, e a plenitude dela: Alegre-se o campo, e todo o que contém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 33, 'Então cantarão as árvores dos bosques diante do SENHOR, Porque vem a julgar a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 34, 'Celebrai a o SENHOR, porque é bom; Porque sua misericórdia é eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 35, 'E dizei: Salva-nos, ó Deus, saúde nossa: Junta-nos, e livra-nos das nações, Para que confessemos tua santo nome, e nos gloriemos em teus louvores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 36, 'Bendito seja o SENHOR Deus de Israel, De eternidade a eternidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 37, 'E deixou ali, diante do arca do pacto do SENHOR, a Asafe e a seus irmãos, para que ministrassem de contínuo diante da arca, cada coisa em seu dia:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 38, 'E a Obede-Edom e a seus irmãos, sessenta e oito; e a Obede-Edom filho de Jedutum, e a Hosa, por porteiros:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 39, 'Assim a Zadoque o sacerdote, e a seus irmãos os sacerdotes, diante do tabernáculo do SENHOR no alto que estava em Gibeão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 40, 'Para que sacrificassem continuamente, a manhã e tarde, holocaustos a o SENHOR no altar do holocausto, conforme a todo o que está escrito na lei do SENHOR, que ele prescreveu a Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 41, 'E com eles a Hemã e a Jedutum, e os outros escolhidos declarados por seus nomes, para glorificar a o SENHOR, porque é eterna sua misericórdia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 42, 'Com eles a Hemã e a Jedutum com trombetas e címbalos para tanger, e com outros instrumentos de música de Deus; e a os filhos de Jedutum, por porteiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 16, 43, 'E todo o povo se foi cada um a sua casa; e Davi se voltou para abençoar sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 1, 'E aconteceu que morando Davi em sua casa, disse Davi ao profeta Natã: Eis aqui eu habito em casa de cedro, e a arca do pacto do SENHOR debaixo de cortinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 2, 'E Natã disse a Davi: Faze tudo o que está em tua coração, porque Deus é contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 3, 'Naquela mesma noite foi palavra de Deus a Natã, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 4, 'Vai e dize a Davi meu servo: Assim disse o SENHOR: Tu não me edificarás casa em que habite:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 5, 'Porque não habitei em casa alguma desde o dia que tirei a os filhos de Israel até hoje; antes estive de tenda em tenda, e de tabernáculo em tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 6, 'Em todo quanto andei com todo Israel falei uma palavra a algum dos juízes de Israel, a os quais mandei que apascentassem meu povo, para dizer-lhes: Por que não me edificais uma casa de cedro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 7, 'Portanto, agora dirás a meu servo Davi: Assim disse o SENHOR dos exércitos: Eu te tomei da malhada, de detrás do gado, para que fosses príncipe sobre meu povo Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 8, 'E fui contigo em tudo quanto andaste, e arranquei a todos teus inimigos de diante de ti, e te fiz grande nome, como o nome dos grandes que são na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 9, 'Assim dispus lugar a meu povo Israel, e o plantei para que habite por si, e que não seja mais comovido: nem os filhos de iniquidade o consumirão mais, como antes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 10, 'E desde o tempo que pus os juízes sobre meu povo Israel; mas humilharei a todos teus inimigos. Faço-te ademais saber que o SENHOR te há de edificar casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 11, 'E será que, quando teus dias forem cumpridos para ir-te com teus pais, levantarei a tua descendência depois de ti, a qual será de teus filhos, e afirmarei seu reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 12, 'Ele me edificará casa, e eu confirmarei seu trono eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 13, 'Eu lhe serei por pai, e ele me será por filho: e não tirarei dele minha misericórdia, como a tirei daquele que foi antes de ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 14, 'Mas eu o confirmarei em minha casa e em meu reino eternamente; e seu trono será firme para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 15, 'Conforme a todas estas palavras, e conforme a toda esta visão, assim falou Natã a Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 16, 'E entrou o rei Davi, e esteve diante do SENHOR, e disse: ó SENHOR Deus, quem sou eu, e qual é minha casa, que me trouxeste até este lugar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 17, 'E ainda isto, ó Deus, te pareceu pouco, pois que falaste da casa de teu servo para mais longe, e me olhaste como a um homem excelente, ó o SENHOR Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 18, 'Que mais pode dizer Davi pedindo de ti para glorificar a tua servo? Porém tu conheces a teu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 19, 'Ó SENHOR, por amor de teu servo e segundo teu coração, fizeste toda esta grandeza, para fazer notórias todas as tuas grandezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 20, 'Ó SENHOR, não há semelhante a ti, nem há Deus a não ser tu, segundo todas as coisas que ouvimos com nossos ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 21, 'E que gente há na terra como teu povo Israel, cujo Deus fosse e se redimisse um povo, para fazer-te nome com grandezas e maravilhas, expulsando as nações de diante de teu povo, que tu resgataste do Egito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 22, 'Tu constituíste a teu povo Israel por povo teu para sempre; e tu, o SENHOR, vieste a ser seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 23, 'Agora, pois, SENHOR, a palavra que falaste acerca de teu servo e de sua casa, seja firme para sempre, e faze como disseste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 24, 'Permaneça, pois, e seja engrandecido teu nome para sempre, a fim de que se diga: o SENHOR dos exércitos, Deus de Israel, é Deus para Israel. E seja a casa de teu servo Davi firme diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 25, 'Porque tu, Deus meu, revelaste ao ouvido a teu servo que lhe edificarás casa; por isso achou teu servo motivo de orar diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 26, 'Agora, pois, o SENHOR, tu és o Deus que falaste de teu servo este bem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 17, 27, 'E agora quiseste abençoar a casa de teu servo, para que permaneça perpetuamente diante de ti: porque tu, o SENHOR, a abençoaste, e será bendita para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 1, 'Depois destas coisas aconteceu que Davi feriu aos filisteus, e os humilhou; e tomou Gate e suas vilas das mãos dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 2, 'Também feriu a Moabe; e os moabitas foram servos de Davi, trazendo-lhe tributos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 3, 'Assim feriu Davi a Hadadezer, rei de Zobá, em Hamate, quando ele foi assegurar seu domínio até o rio Eufrates.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 4, 'E tomou-lhes Davi mil carros, e sete mil a cavalo, e vinte mil homens a pé; e Davi aleijou os cavalos de todos os carros, exceto os de cem carros que deixou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 5, 'E vindo os sírios de Damasco em ajuda de Hadadezer, rei de Zobá, Davi feriu dos sírios vinte e dois mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 6, 'E Davi pôs guarnições na Síria de Damasco, e os sírios foram feitos servos de Davi, trazendo-lhe tributos; porque o SENHOR dava vitória a Davi por onde quer que fosse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 7, 'Tomou também Davi os escudos de ouro que levavam os servos de Hadadezer, e trouxe-os a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 8, 'Assim de Tibate e de Cum, cidades de Hadadezer, Davi tomou muito bronze, de que Salomão fez o mar de bronze, as colunas, e vasos de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 9, 'E ouvindo Toú, rei de Hamate, que Davi havia defeito todo o exército de Hadadezer, rei de Zobá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 10, 'Enviou seu filho Hdorão ao rei Davi para saudar-lhe e para bendizer-lhe por haver guerreado com Hadadezer, e haver lhe vencido; porque Toú tinha guerra com Hadadezer. Enviou-lhe também toda sorte de artigos de ouro, de prata e de metal;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 11, 'os quais o rei Davi dedicou a o SENHOR, com a prata e ouro que havia tomado de todas as nações, de Edom, de Moabe, dos filhos de Amom, dos filisteus, e de Amaleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 12, 'Além disso Abisai, filho de Zeruia, feriu no vale do sal dezoito mil edomitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 13, 'E pôs guarnições em Edom, e todos os edomitas foram servos de Davi; porque o SENHOR guardava a Davi por onde quer que fosse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 14, 'E reinou Davi sobre todo Israel, e fazia juízo e justiça a todo seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 15, 'E Joabe, filho de Zeruia, era general do exército; e Josafá filho de Ailude, cronista;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 16, 'E Zadoque, filho de Aitube, e Abimeleque filho de Abiatar, eram sacerdotes; e Sausa, secretário;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 18, 17, 'E Benaia, filho de Joiada, era sobre os quereteus e peleteus; e os filhos de Davi eram os principais próximos do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 1, 'Depois destas coisas, aconteceu que morreu Naás, rei dos filhos de Amom, e seu filho reinou em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 2, 'E disse Davi: Farei misericórdia com Hanã filho de Naás, porque também seu pai fez comigo misericórdia. Assim Davi enviou embaixadores que o consolassem da morte de seu pai. Mas vindos os servos de Davi na terra dos filhos de Amom a Hanã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 3, 'os príncipes dos filhos de Amom disseram a Hanã: Pensas que Davi está honrando o teu pai, de maneira que te enviou consoladores? Acaso não é que os servos dele vêm a ti para espionar, e investigar, e reconhecer a terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 4, 'Então Hanã tomou os servos de Davi, rapou-os, e cortou-lhes as vestes ao meio, até as nádegas, e despachou-os.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 5, 'Foram-se, pois, e quando foi dada a Davi a notícia acerca daqueles homens, ele mandou que fossem ao encontro deles, porque estavam muito afrontados. E o rei mandou-lhes dizer: Ficai em Jericó até que vos cresça a barba, e então voltareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 6, 'E quando os filhos de Amom viram que se haviam feito Davi ter ódio deles, Hanã e os filhos de Amom enviaram mil talentos de prata, para alugarem carruragens e cavaleiros da Mesopotâmia, da Síria de Maaca, e de Zobá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 7, 'E alugaram trinta e dois mil carruagens, e ao rei de Maaca com o seu povo, os quais vieram e assentaram seu acampamento diante de Medeba. E juntaram-se também os filhos de Amom de suas cidades, e vieram à guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 8, 'Ouvindo-o Davi, enviou a Joabe com todo o exército dos homens valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 9, 'E os filhos de Amom saíram, e ordenaram sua tropa à entrada da cidade; e os reis que haviam vindo, estavam à parte no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 10, 'E vendo Joabe que a linha da batalha estava contra ele pela frente e por trás, escolheu de todos os mais capacitados que havia em Israel, e pôs seu esquadrão em formação contra os sírios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 11, 'Depois pôs os outros nas mãos de seu irmão Abisai, que os pôes em formação de batalha contra os amonitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 12, 'E disse: Se os sírios forem mais fortes que eu, tu me socorrerás; e se os amonitas forem mais fortes que tu, eu te socorrerei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 13, 'Esforça-te, e sejamos corajosos por nosso povo, e pelas cidades de nosso Deus; e faça o SENHOR o que bem lhe parecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 14, 'Aproximou-se, então, Joabe e o povo que tinha consigo, para lutar contra os sírios; mas eles fugiram diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 15, 'E os filhos de Amom, vendo que os sírios haviam fugido, fugiram também eles diante de Abisai seu irmão, e entraram-se na cidade. Então Joabe se voltou a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 16, 'E vendo os sírios que haviam caído diante de Israel, enviaram embaixadores, e trouxeram aos sírios que estavam da outra parte do rio, cujo capitão era Sofaque, general do exército de Hadadezer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 17, 'Logo que foi dado aviso a Davi, juntou a todo Israel, e passando o Jordão veio a eles, e ordenou contra eles seu exército. E como Davi havia ordenado sua tropa contra eles, os sírios lutaram com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 18, 'Mas os sírios fugiram diante de Israel; e Davi matou dos sírios sete mil homens das carruagens, e quarenta mil homens a pé; assim matou Sofaque, general do exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 19, 19, 'E vendo os sírios de Hadadezer que haviam caído diante de Israel, concordarem em fazer a paz com Davi, e foram seus servos; e nunca mais os sírios quiseram ajudar os filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 20, 1, 'E aconteceu à volta do ano, no tempo que costumam os reis sair à guerra, que Joabe tirou as forças do exército, e destruiu a terra dos filhos de Amom, e veio e cercou a Rabá. Mas Davi estava em Jerusalém; e Joabe atacou Rabá, e a destruiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 20, 2, 'E tomou Davi a coroa de seu rei de encima de sua cabeça, e achou-a de peso de um talento de ouro, e havia nela pedras preciosas; e foi posta sobre a cabeça de Davi. E ademais de isto tirou da cidade um muito grande despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 20, 3, 'Tirou também ao povo que estava nela, e cortou-os com serras, e com trilhos de ferro, e machados. O mesmo fez Davi a todas as cidades dos filhos de Amom. E voltou-se Davi com todo o povo a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 20, 4, 'Depois de isto aconteceu que se levantou guerra em Gezer com os filisteus; e feriu Sibecai Husatita a Sipai, da linhagem dos gigantes; e foram humilhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 20, 5, 'E voltou-se a levantar guerra com os filisteus; e feriu Elanã filho de Jair a Lami, irmão de Golias geteu, a haste de cuja lança era como um lançador de tecedores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 20, 6, 'E voltou a haver guerra em Gate, de onde havia um homem de grande estatura, o qual tinha seis dedos em pés e mãos, em todos vinte e quatro: e também era filho de Rafa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 20, 7, 'Insultou ele a Israel, mas feriu-o Jônatas, filho de Simeia irmão de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 20, 8, 'Estes foram filhos de Rafa em Gate, os quais caíram por mão de Davi e de seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 1, 'Mas Satanás se levantou contra Israel, e incitou a Davi a que contasse a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 2, 'E disse Davi a Joabe e a os príncipes do povo: Ide, contai a Israel desde Berseba até Dã, e trazei-me o número deles para que eu o saiba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 3, 'E disse Joabe: Acrescente o SENHOR a seu povo cem vezes outros tantos. Rei senhor meu, não são todos estes servos de meu senhor? Para que procura meu senhor isto, que será pernicioso a Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 4, 'Mas o mandamento do rei pode mais que Joabe. Saiu por tanto Joabe, e foi por todo Israel; e voltou a Jerusalém, e deu a conta do número do povo a Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 5, 'E achou-se em todo Israel que tiravam espada, onze vezes cem mil; e de Judá quatrocentos e setenta mil homens que tiravam espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 6, 'Entre estes não foram contados os levitas, nem os filhos de Benjamim, porque Joabe abominava o mandamento do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 7, 'Assim desagradou este negócio a os olhos de Deus, e feriu a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 8, 'E disse Davi a Deus: Pequei gravemente em fazer isto: rogo-te que faças passar a iniquidade de teu servo, porque eu ei feito muito loucamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 9, 'E falou o SENHOR a Gade, vidente de Davi, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 10, 'Vai, e fala a Davi, e dize-lhe: Assim disse o SENHOR: Três coisas te proponho; escolhe de elas uma que eu faça contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 11, 'E vindo Gade a Davi, disse-lhe: Assim disse o SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 12, 'Escolhe-te, ou três anos de fome; ou ser por três meses defeito diante de teus inimigos, e que a espada de teus adversários te alcance; ou por três dias a espada do SENHOR e pestilência na terra, e que o anjo do SENHOR destrua em todo o termo de Israel. Olha, pois, o que responderá ao que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 13, 'Então Davi disse a Gade: Estou em grande angústia: rogo que eu caia na mão do SENHOR; porque suas misericórdias são muitas em extremo, e que não caia eu em mãos de homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 14, 'Assim o SENHOR deu pestilência em Israel, e caíram de Israel setenta mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 15, 'E enviou o SENHOR o anjo a Jerusalém para destruí-la: mas estando ele destruindo, olhou o SENHOR, e arrependeu-se daquele mal,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 16, 'E levantando Davi seus olhos, viu ao anjo do SENHOR, que estava entre o céu e a terra, tendo uma espada nua em sua mão, estendida contra Jerusalém. Então Davi e os anciãos se prostraram sobre seus rostos, cobertos de sacos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 17, 'E disse Davi a Deus: Não sou eu o que fez contar o povo? Eu mesmo sou o que pequei, e certamente fiz mal; mas estas ovelhas, que fizeram? Ó SENHOR, Deus meu, seja agora tua mão contra mim, e contra a casa de meu pai, e não haja praga em teu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 18, 'E o anjo do SENHOR ordenou a Gade que dissesse a Davi, que subisse e construísse um altar a o SENHOR na era de Ornã jebuseu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 19, 'Então Davi subiu, conforme a palavra de Gade que lhe havia dito em nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 20, 'E voltando-se Ornã viu o anjo; pelo que se esconderam quatro filhos seus que com ele estavam. E Ornã trilhava o trigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 21, 'E vindo Davi a Ornã, olhou este, e viu a Davi: e saindo da eira, prostrou-se em terra a Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 22, 'Então disse Davi a Ornã: Dá-me este lugar da eira, em que edifique um altar a o SENHOR, e dá-o a mim por seu devido preço, para que cesse a praga do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 23, 'E Ornã respondeu a Davi: Toma-o para ti, e faça meu senhor o rei o que bem lhe parecer; e ainda os bois darei para o holocausto, e os trilhos para lenha, e trigo para a oferta de alimentos; eu dou tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 24, 'Então o rei Davi disse a Ornã: Não, mas sim que efetivamente a comprarei por seu justo preço: porque não tomarei para o SENHOR o que é teu, nem sacrificarei holocausto que nada me custe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 25, 'E deu Davi a Ornã pelo lugar seiscentos siclos de ouro por peso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 26, 'E edificou ali Davi um altar a o SENHOR, em o que ofereceu holocaustos e sacrifícios pacíficos, e invocou a o SENHOR, o qual lhe respondeu por fogo dos céus em o altar do holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 27, 'E como o SENHOR falou ao anjo, ele voltou sua espada à bainha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 28, 'Então vendo Davi que o SENHOR lhe havia ouvido na eira de Ornã jebuseu, sacrificou ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 29, 'E o tabernáculo do SENHOR que Moisés havia feito no deserto, e o altar do holocausto, estavam então no alto de Gibeão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 21, 30, 'Mas Davi não pode ir ali a consultar a Deus, porque estava espantado por causa da espada do anjo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 1, 'E disse Davi: Esta é a casa do SENHOR Deus, e este é o altar do holocausto para Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 2, 'Depois mandou Davi que se juntassem os estrangeiros que estavam na terra de Israel, e assinalou deles pedreiros que lavrassem pedras para edificar a casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 3, 'Assim preparou Davi muito ferro para os pregos das portas, e para as junturas; e muito metal sem peso, e madeira de cedro sem conta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 4, 'Porque os sidônios e tírios haviam trazido a Davi madeira de cedro inumerável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 5, 'E disse Davi: Salomão meu filho é jovem e tenro, e a casa que se há de edificar a o SENHOR há de ser magnífica por excelência, para nome e honra em todas as terras; agora pois eu lhe prepararei o necessário. E preparou Davi antes de sua morte em grande abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 6, 'Chamou então Davi a Salomão seu filho, e mandou-lhe que edificasse casa a o SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 7, 'E disse Davi a Salomão: Filho meu, em meu coração tive o edificar templo ao nome do SENHOR meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 8, 'Mas veio a mim palavra do SENHOR, dizendo: Tu derramaste muito sangue, e trouxeste grandes guerras: não edificarás casa a meu nome, porque derramaste muito sangue na terra diante de mim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 9, 'Eis aqui, um filho te nascerá, o qual será homem de repouso, porque eu lhe darei quietude de todos seus inimigos em derredor; por tanto seu nome será Salomão; e eu darei paz e repouso sobre Israel em seus dias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 10, 'Ele edificará casa a meu nome, e ele me será a mim por filho, e eu lhe serei por pai; e afirmarei o trono de seu reino sobre Israel para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 11, 'Agora, pois, filho meu, seja contigo o SENHOR, e sejas próspero, e edifiques casa a o SENHOR teu Deus, como ele disse de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 12, 'E o SENHOR te dê entendimento e prudência, e ele te dê mandamentos para Israel; e que tu guardes a lei do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 13, 'Então serás próspero, se cuidares de pôr por obra os estatutos e direitos que o SENHOR mandou a Moisés para Israel. Esforça-te pois, e recobra ânimo; não temas, nem desmaies.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 14, 'Eis aqui, eu em minha estreiteza preveni para a casa do SENHOR cem mil talentos de ouro, e um milhar de milhares de talentos de prata: não tem peso o metal nem o ferro, porque é muito. Assim aprontei madeira e pedra, a o qual tu acrescentarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 15, 'Tu tens contigo muitos oficiais, pedreiros, pedreiros, e carpinteiros, e todo homem especialista em toda obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 16, 'Do ouro, da prata, do metal, e do ferro, não há número. Levanta-te, pois, e à obra; que o SENHOR será contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 17, 'Assim mandou Davi a todos os principais de Israel que dessem ajuda a Salomão seu filho, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 18, 'Não é convosco o SENHOR vosso Deus, o qual vos há dado quietude de todas as partes? Porque ele entregou em minha mão os moradores da terra, e a terra há sido sujeitada diante do SENHOR, e diante de seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 22, 19, 'Ponde, pois, agora vossos corações e vossos ânimos em buscar a o SENHOR vosso Deus; e levantai-vos, e edificai o santuário do Deus o SENHOR, para trazer a arca do pacto do SENHOR, e o santos vasos de Deus, à casa edificada ao nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 1, 'Sendo, pois, Davi já velho e farto de dias, fez a Salomão seu filho rei sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 2, 'E juntando a todos os principais de Israel, e a os sacerdotes e levitas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 3, 'Foram contados os levitas de trinta anos acima; e foi o número deles por suas cabeças, contados um a um, trinta e oito mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 4, 'Destes, vinte e quatro mil para dar pressa à obra da casa do SENHOR; e governadores e juízes, seis mil;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 5, 'Ademais quatro mil porteiros; e quatro mil para louvar a o SENHOR, disse Davi, com os instrumentos que fiz para render louvores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 6, 'E repartiu-os Davi em ordens conforme a os filhos de Levi, Gérson e Coate e Merari.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 7, 'Os filhos de Gérson: Ladã, e Simei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 8, 'Os filhos de Ladã, três: Jeiel o primeiro, depois Zetã e Joel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 9, 'Os filhos de Simei, três: Selomote, Haziel, e Harã. Estes foram os príncipes das famílias de Ladã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 10, 'E os filhos de Simei: Jaate, Zina, Jeus, e Berias. Estes quatro foram os filhos de Simei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 11, 'Jaate era o primeiro, Zina o segundo; mas Jeus e Berias não multiplicaram em filhos, por o qual foram contados por uma família.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 12, 'Os filhos de Coate: Anrão, Izar, Hebrom, e Uziel, eles quatro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 13, 'Os filhos de Anrão: Arão e Moisés. E Arão foi apartado para ser dedicado às mais santas coisas, ele e seus filhos para sempre, para que queimassem perfumes diante do SENHOR, e lhe ministrassem, e bendisessem em seu nome, para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 14, 'E os filhos de Moisés, homem de Deus, foram contados na tribo de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 15, 'Os filhos de Moisés foram Gérson e Eliézer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 16, 'Filho de Gérson foi Sebuel o primeiro.')
